CREATE SCHEMA IF NOT EXISTS acct;
CREATE SEQUENCE revinfo_seq START WITH 1 INCREMENT BY 50;

CREATE TABLE cms_article (
    created_by VARCHAR(50),
    create_date TIMESTAMP,
    last_modified_by VARCHAR(50),
    last_modified_date TIMESTAMP,
    article_id VARCHAR(36) NOT NULL,
    title VARCHAR(300) NOT NULL,
    slug VARCHAR(300) NOT NULL,
    summary VARCHAR(500),
    body CHARACTER VARYING,
    body_text CHARACTER VARYING,
    publish_date TIMESTAMP,
    view_count BIGINT,
    featured BOOLEAN,
    article_status VARCHAR(3),
    category_category_id BIGINT,
    ratings VARCHAR(255),
    labels VARCHAR(255),
    PRIMARY KEY (article_id)
);

CREATE TABLE cms_article_tags (
    article_article_id VARCHAR(36) NOT NULL,
    tags_tag_id BIGINT NOT NULL
);

CREATE TABLE cms_article_hist (
    rev INTEGER NOT NULL,
    revtype TINYINT,
    article_id VARCHAR(36) NOT NULL,
    created_by VARCHAR(50),
    create_date TIMESTAMP,
    last_modified_by VARCHAR(50),
    last_modified_date TIMESTAMP,
    title VARCHAR(300),
    slug VARCHAR(300),
    summary VARCHAR(500),
    body CHARACTER VARYING,
    body_text CHARACTER VARYING,
    publish_date TIMESTAMP,
    view_count BIGINT,
    featured BOOLEAN,
    article_status VARCHAR(3),
    ratings VARCHAR(255),
    labels VARCHAR(255),
    PRIMARY KEY (article_id, rev)
);

CREATE TABLE cms_attachment (
